export function resolveCorporateReferences(rows:Record<string,unknown>[],lookups:Lookup[]){
 const companies=lookups.filter(item=>item.kind==='companies');if(companies.length!==1)throw new Error('Configure exactly one active Company master before importing the Corporate / HO workbook');
 return rows.map(row=>{const resolved:Record<string,unknown>={...row,companyId:companies[0].id};for(const [field,kind] of Object.entries(corporateReferences)){const value=String(row[field]??'').trim().toLowerCase();if(!value){resolved[field]='';continue;}const siteAliases:Record<string,string>={'dudichua ob east':'ncl-dude','dudhichua ob east':'ncl-dude','dudichua ob west':'ncl-dudw','dudhichua ob west':'ncl-dudw','jayant ob':'ncl-jayant'};const matches=lookups.filter(item=>item.kind===kind&&[item.code,item.name].some(candidate=>candidate.trim().toLowerCase()===value||field==='siteId'&&candidate.trim().toLowerCase()===siteAliases[value]));resolved[field]=matches.length===1?matches[0].id:'';}return resolved;});
}
