type AadhaarRead={text:string;quality:string};
function enhancedAadhaar(bitmap:ImageBitmap){const max=2200,scale=Math.min(2,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d',{willReadFrequently:true});if(!context)return {canvas,quality:''};context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high';context.drawImage(bitmap,0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height),data=image.data;let brightness=0,edges=0,samples=0,previous=0;for(let y=0;y<canvas.height;y+=4)for(let x=0;x<canvas.width;x+=4){const i=(y*canvas.width+x)*4,gray=.299*data[i]+.587*data[i+1]+.114*data[i+2];brightness+=gray;if(samples&&x>0)edges+=Math.abs(gray-previous);previous=gray;samples++;}const average=brightness/Math.max(1,samples),sharpness=edges/Math.max(1,samples);for(let i=0;i<data.length;i+=4){const gray=.299*data[i]+.587*data[i+1]+.114*data[i+2],adjusted=Math.max(0,Math.min(255,(gray-average)*1.65+145));data[i]=data[i+1]=data[i+2]=adjusted;}context.putImageData(image,0,0);const quality=sharpness<7?'The image appears blurred. Enhanced reading was applied; please verify every detected field.':average<65?'The image is dark. Enhanced reading was applied; please verify every detected field.':average>225?'The image has strong glare. Enhanced reading was applied; please verify every detected field.':'';return {canvas,quality};}
async function canvasBlob(canvas:HTMLCanvasElement){return await new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Unable to enhance image')),'image/png'));}
