async function readAadhaarText(file:File):Promise<AadhaarRead>{const texts:string[]=[],focused:Blob[]=[];let enhanced:Blob|undefined,quality='';try{if('createImageBitmap'in window){const bitmap=await createImageBitmap(file);try{const prepared=enhancedAadhaar(bitmap);quality=prepared.quality;enhanced=await canvasBlob(prepared.canvas);focused.push(...await focusedAadhaarBlobs(prepared.canvas));const BarcodeDetector=(window as unknown as {BarcodeDetector?:new(options:{formats:string[]})=>{detect:(source:ImageBitmap)=>Promise<{rawValue?:string}[]>}}).BarcodeDetector;if(BarcodeDetector){const codes=await new BarcodeDetector({formats:['qr_code']}).detect(bitmap);texts.push(...codes.map(code=>code.rawValue||''));}const TextDetector=(window as unknown as {TextDetector?:new()=>{detect:(source:ImageBitmap)=>Promise<{rawValue?:string}[]>}}).TextDetector;if(TextDetector){const blocks=await new TextDetector().detect(bitmap);texts.push(...blocks.map(block=>block.rawValue||''));}}finally{bitmap.close();}}}catch{/* Continue with OCR when native detection or preprocessing is unavailable. */}const{createWorker}=await import('tesseract.js'),sources:Blob[]=[...(enhanced?[enhanced]:[file]),...focused],worker=await createWorker('eng');try{for(const source of sources){const result=await worker.recognize(source);texts.push(result.data.text);}}finally{await worker.terminate();}return {text:texts.filter(Boolean).join('\n'),quality};}

