 if(activeStep==='Mine Compliance (OB / COAL where applicable)')return <Section title="Mine Compliance (OB / COAL where applicable)"><div className="joining-grid"><Field label="VT Certificate No." placeholder="Required as applicable"/><Field label="VTC Centre Name" placeholder="Training centre"/><Field label="VTC Valid Upto" type="date"/><Field label="WUIN No." placeholder="If applicable"/><Field label="Medical Examination Date" required type="date"/><Field label="Medical Fitness Valid Upto" type="date"/><Field label="Medical Fitness Status" options={['Fit','Pending','Unfit']}/><Field label="Safety Induction Date" type="date"/><Field label="Driving Licence No." placeholder="Mandatory for drivers/operators where applicable"/><Field label="DL Class" options={['LMV','HMV','Transport','Other']}/><Field label="DL Issue Date" type="date"/><Field label="DL Valid Upto" type="date"/><Field label="Operator Competency Certificate" placeholder="No. / type / validity"/><Field label="Other Mine Permit / Training" type="textarea" wide placeholder="Details"/></div></Section>;
