 useEffect(()=>{if(draft&&formRef.current){restoreJoiningFields(formRef.current,draft.fields);restoreJoiningFiles(formRef.current,draft.files||{});}const form=formRef.current;const changed=()=>{dirty.current=true;latestPersist.current();};form?.addEventListener('input',changed);form?.addEventListener('change',changed);const flush=()=>latestPersist.current();window.addEventListener('pagehide',flush);return()=>{flush();form?.removeEventListener('input',changed);form?.removeEventListener('change',changed);window.removeEventListener('pagehide',flush);};},[]);
 useEffect(()=>{if(defaults.site||defaults.department||defaults.joiningCategory)dirty.current=true;latestPersist.current();},[step,employeeCategory,defaults.joiningCategory,defaults.site,defaults.department,defaults.subdepartment,defaults.designation,photo]);
