 async function importEmployees(event:ChangeEvent<HTMLInputElement>){
  const file=event.target.files?.[0];if(!file)return;
  setImportStatus('');setImportError('');
  try{
   const extension=file.name.split('.').pop()?.toLowerCase();let rows:Record<string,unknown>[];
   if(!['xlsx','xls','csv'].includes(extension||''))throw new Error('Choose an Excel or CSV file (.xlsx, .xls or .csv)');
   const selectedGroup=employeeSheetsFor(employeeGroup).find(group=>group.name===existingType)||employeeSheets[0];
   if(extension==='csv'){if(tab!=='Update Existing Employee')throw new Error('CSV import is available inside each Update Existing Employee section');const items=parseCsv(await file.text()),headers=Object.keys(items[0]||{});if(headers.length!==selectedGroup.columns.length||headers.some((header,index)=>header!==selectedGroup.columns[index]))throw new Error(`${existingType}: use the exact exported columns`);rows=items.filter(item=>String(item['Employee Code']??'').trim()).map(item=>({...corporateImportRow(item),__section:existingType,__sectionData:item}));}
   else{const workbook=read(await file.arrayBuffer(),{type:'array'}),sheet=workbook.Sheets[workbook.SheetNames[0]];if(!sheet)throw new Error('The workbook does not contain a worksheet');const selectedSheet=workbook.Sheets[existingType]||sheet;if(tab==='Update Existing Employee'){const grid=utils.sheet_to_json<unknown[]>(selectedSheet,{header:1,defval:''}),headers=(grid[0]||[]).map(value=>String(value).trim());if(headers.length!==selectedGroup.columns.length||headers.some((header,index)=>header!==selectedGroup.columns[index]))throw new Error(`${existingType}: use the exact exported columns`);rows=utils.sheet_to_json<Record<string,unknown>>(selectedSheet,{defval:''}).filter(item=>String(item['Employee Code']??'').trim()).map(item=>({...corporateImportRow(item),__section:existingType,__sectionData:item}));}else{const hasSectionSheets=employeeSheets.every(group=>workbook.SheetNames.includes(group.name));if(hasSectionSheets){const merged=new Map<string,Record<string,unknown>>();for(const group of employeeSheets){const section=workbook.Sheets[group.name],grid=utils.sheet_to_json<unknown[]>(section,{header:1,defval:''}),headers=(grid[0]||[]).map(value=>String(value).trim());if(headers.length!==group.columns.length||headers.some((header,index)=>header!==group.columns[index]))throw new Error(`${group.name}: use the exact exported columns`);for(const item of utils.sheet_to_json<Record<string,unknown>>(section,{defval:''})){const code=String(item['Employee Code']??'').trim();if(!code)continue;merged.set(code,{...(merged.get(code)||{}),...item});}}rows=Array.from(merged.values()).map(corporateImportRow);}else{const grid=utils.sheet_to_json<unknown[]>(sheet,{header:1,defval:''});if(!validCorporateOfficeHeaders(grid[0]||[]))throw new Error('Use the six-sheet Corporate / HO employee workbook');rows=utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:''}).map(corporateImportRow);}}}
   if(!rows.length||rows.length>500)throw new Error('Choose a file with 1–500 employee rows');
   const invalidIndex=rows.findIndex(row=>!row.code||(tab!=='Update Existing Employee'&&!row.name));if(invalidIndex>=0){const row=rows[invalidIndex];throw new Error(`Row ${invalidIndex+2}${row.name?` (${row.name})`:''}: ${!row.code?'Employee Code':'Full Name *'} is required`);}
   setImportRows(rows);
   setImportStatus(`${file.name} ready · ${rows.length} employee ${rows.length===1?'row':'rows'} loaded`);
  }catch(error){setImportRows([]);setImportError((error as Error).message);}finally{event.target.value='';}
 }
 async function saveImport(){if(!grant||!importRows.length)return;setImportBusy(true);setImportError('');try{if(importRows[0].__section){for(const imported of importRows){const row=visibleEmployees.find(employee=>employee.code===imported.code);if(!row)throw new Error(`Employee Code ${imported.code} was not found`);const sectionData=imported.__sectionData as Record<string,unknown>,currentOffice=(row.data.officeData&&typeof row.data.officeData==='object'?row.data.officeData:{}) as Record<string,unknown>,officeData={...currentOffice,...sectionData};await api(grant,`records/employees/${row.id}`,'PUT',{...row.data,code:row.code,name:String(sectionData['Full Name *']||row.name),officeData,version:row.version});}notice?.(`${importRows.length} employee ${existingType} records updated`);}else{const lookups=await api<Lookup[]>(grant,'lookups'),records=resolveCorporateReferences(importRows,lookups),result=await api<{imported:number}>(grant,'import/employees','POST',{records});notice?.(`${result.imported} employee drafts saved to Azure`);}setImportRows([]);setImportStatus('');setEmployeesVersion(version=>version+1);setTab('Update Existing Employee');}catch(error){setImportError((error as Error).message);}finally{setImportBusy(false);}}
